// GENERATED by engine/wrappers.py -- self-checking replay of vectors/d_trip.vec against rtl/tops/top_d_trip.v.
// Each vector line is one clock cycle: inputs and register flips are applied in the low phase, outputs are compared
// 2 ns later, then the rising edge. A flip XORs a register for that cycle only (as Core.step(flips=...) does).
// Run (from the secboot_hw directory):
//   iverilog -g2005 -o build/sim/tb_d_trip.vvp -DVEC='"vectors/d_trip.vec"' rtl/*.v rtl/tops/top_d_trip.v tb/gen/tb_d_trip.v
//   vvp build/sim/tb_d_trip.vvp        (prints PASS or FAIL)
`timescale 1ns/1ps
`ifndef VEC
`define VEC "vectors/d_trip.vec"
`endif
module tb_d_trip;
  reg clk;
  reg [7:0] sig;
  wire [7:0] goal;
  top_d_trip dut (.clk(clk), .sig(sig), .boot_word(goal));

  integer fd, rc, errors, cycles, scen;
  reg [255:0] v0, v1, v2, v3, v4, v5, v6, v7, v8, v9, v10, v11, v12, v13, v14, v15, v16, v17;

  task flip(input [31:0] id, input [255:0] m);
    begin
      case (id)
        0: ;
        1: dut.u_core.st = dut.u_core.st ^ m[7:0];
        2: dut.u_core.rel = dut.u_core.rel ^ m[7:0];
        3: dut.u_core.blk = dut.u_core.blk ^ m[0:0];
        4: dut.u_core.rnd = dut.u_core.rnd ^ m[4:0];
        5: dut.u_core.cph = dut.u_core.cph ^ m[0:0];
        6: dut.u_core.tok = dut.u_core.tok ^ m[7:0];
        7: dut.u_core.g_flag[0].q = dut.u_core.g_flag[0].q ^ m[0:0];
        8: dut.u_core.g_flag[1].q = dut.u_core.g_flag[1].q ^ m[0:0];
        9: dut.u_core.g_flag[2].q = dut.u_core.g_flag[2].q ^ m[0:0];
        default: begin $display("FAIL bad flip id %0d", id); errors = errors + 1; end
      endcase
    end
  endtask

  task restore;
    begin
      dut.u_core.st = 8'hF0;
      dut.u_core.rel = 8'hF0;
      dut.u_core.blk = 1'h0;
      dut.u_core.rnd = 5'h0;
      dut.u_core.cph = 1'h0;
      dut.u_core.tok = 8'h0;
      dut.u_core.g_flag[0].q = 1'h0;
      dut.u_core.g_flag[1].q = 1'h0;
      dut.u_core.g_flag[2].q = 1'h0;
    end
  endtask

  task chk(input [255:0] got, input [255:0] want, input [8*8-1:0] what);
    begin
      if (got !== want) begin
        errors = errors + 1;
        if (errors <= 20)
          $display("MISMATCH scenario %0d cycle %0d %0s: got %0h want %0h", scen, cycles, what, got, want);
      end
    end
  endtask

  task readline;
    begin
      rc = $fscanf(fd, "%h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h %h\n",
                   v0, v1, v2, v3, v4, v5, v6, v7, v8, v9, v10, v11, v12, v13, v14, v15, v16, v17);
    end
  endtask

  initial begin   // watchdog: a hang (for example a vector-format mismatch) fails instead of blocking vvp
    #10000000;
    $display("FAIL timeout");
    $finish;
  end

  initial begin
    clk = 1'b0; sig = 8'h00; errors = 0; cycles = 0; scen = 0;
    fd = $fopen(`VEC, "r");
    if (fd == 0) begin $display("FAIL cannot open %0s", `VEC); $finish; end
    #1;
    readline;
    while (rc == 18) begin
      if (v0 == 1) begin
        restore;
        scen = scen + 1;
        cycles = 0;
      end else begin
        sig = v1[7:0];
        flip(v2, v3); flip(v4, v5); flip(v6, v7); flip(v8, v9);
        #2;
        chk(goal, v10, "goal");
        chk(dut.u_core.state, v11, "state");
        chk(dut.u_core.boot_word, v12, "word");
        chk(dut.u_core.boot_token, v13, "token");
        chk(dut.u_core.alarm, v14, "alarm");
        chk(dut.u_core.busy, v15, "busy");
        chk(dut.u_core.done, v16, "done");
        chk(dut.u_core.blk_ready, v17, "ready");
        #3 clk = 1'b1;
        #5 clk = 1'b0;
        cycles = cycles + 1;
      end
      readline;
    end
    if (!$feof(fd)) begin
      $display("FAIL malformed vector line (%0d fields read)", rc); errors = errors + 1;
    end
    $fclose(fd);
    if (errors == 0 && scen > 0)
      $display("PASS tb_d_trip: %0d scenarios", scen);
    else
      $display("FAIL tb_d_trip: %0d mismatches, %0d scenarios", errors, scen);
    $finish;
  end
endmodule
